/* Offline cache for Cung Tường Mộng (generated by dev/site/build_site.sh from dev/site/sw.tpl.js; do not edit sw.js by hand).
   Build 92ce2b0e143e — this file's bytes change exactly when the build changes (V = content hash of index.html + shell files), so the browser
   installs a new worker on the next check (dev/site/swreg.js checks on open and every return to the foreground).
   New build: install fills the new shell → skipWaiting → activate drops old shells + stale assets → clients.claim → every open page gets
   'controllerchange' and opens the new build (kit card "Có bản mới", KIT §35.2). Saved games live in localStorage: never touched here.
   index.html is always network first (no HTTP cache, cache:'no-cache'); the saved copy answers only offline or after 4 s on a slow line.
   Two caches:
   - SHELL  'ctm-shell-<v>'  index.html, manifest, assets.json, the JSON data files, icons. Small; replaced on every build that changes them.
   - ASSETS 'ctm-assets'     every image and sound, keyed by content: '<path>?h=<sha256/16>'. Long-lived, NEVER wiped by a build:
                             a changed file gets a new key (only it downloads), a removed/changed file's old key is pruned on activate.
   Filling ASSETS with progress is the page's job (dev/build/jload.js); this worker only serves it and caches what the game asks for.
   Only same-origin GETs are handled: the co-op worker (ctm-coop…workers.dev, fetch + WebSocket) and any other origin go straight to the network. */
const V='92ce2b0e143e';
const SHELL='ctm-shell-'+V, ASSETS='ctm-assets';
const PRE=["index.html","assets.json","audio/MANIFEST.json","audio/VOICES.json","img/ACTS.json","img/EVENTS.json","img/FIGURES-kids.json","img/FIGURES-others.json","img/FIGURES-servants.json","img/FIGURES.json","img/INFO.json","img/MANIFEST.json","img/map-hotspots.json","img/scar-fit.json","img/veil-fit.json","manifest.webmanifest"];
let MAN=null;
function man(){if(MAN)return MAN;MAN=caches.open(SHELL).then(c=>c.match('assets.json')).then(r=>r?r:fetch('assets.json',{cache:'no-store'})).then(r=>r.json()).then(j=>{const m=new Map();for(const f of j.files)m.set(f[0],f[1]);return m}).catch(e=>{MAN=null;return new Map()});return MAN}
self.addEventListener('install',e=>{e.waitUntil(caches.open(SHELL).then(c=>c.addAll(PRE.map(u=>new Request(u,{cache:'reload'})))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil((async()=>{
 const ks=await caches.keys();
 /* old shells go; legacy 'ctm-<timestamp>' caches stay until jload.js has moved their matching files into ASSETS */
 await Promise.all(ks.filter(k=>k.startsWith('ctm-shell-')&&k!==SHELL).map(k=>caches.delete(k)));
 MAN=null;await self.clients.claim()})());
 /* pruning assets no longer in assets.json walks ~10k keys: done after activation (outside waitUntil) so fetches, and the page
    reopening on the new build, never wait for it */
 setTimeout(prune,3000)});
let pruned=false;
async function prune(){if(pruned)return;pruned=true;try{const m=await man();if(!m.size)return;const c=await caches.open(ASSETS);
 for(const r of await c.keys()){const u=new URL(r.url),p=u.pathname.slice(scopePath().length);if(m.get(p)!==u.searchParams.get('h'))await c.delete(r)}}catch(e){pruned=false}}
/* a page may ask a waiting worker to take over (swreg.js), or ask which build answers it (tests) */
self.addEventListener('message',e=>{const d=e.data||{};if(d.ctm==='skip')self.skipWaiting();else if(d.ctm==='v'&&e.source)e.source.postMessage({ctm:'v',v:V})});
function scopePath(){return new URL(self.registration.scope).pathname}
function relPath(u){const s=scopePath();return u.pathname.startsWith(s)?decodeURIComponent(u.pathname.slice(s.length)):null}
/* Range requests (<audio> elements) get a 206 cut from the cached whole file */
async function ranged(req,res){const rg=req.headers.get('range');if(!rg||!res||res.status!==200)return res;
 const m=/bytes=(\d*)-(\d*)/.exec(rg);if(!m)return res;const b=await res.blob(),n=b.size;
 let s=m[1]===''?Math.max(0,n-(+m[2])):+m[1],t=m[1]===''||m[2]===''?n-1:Math.min(+m[2],n-1);if(s>=n)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+n}});
 return new Response(b.slice(s,t+1),{status:206,headers:{'Content-Type':res.headers.get('Content-Type')||'application/octet-stream','Content-Range':`bytes ${s}-${t}/${n}`,'Content-Length':String(t-s+1),'Accept-Ranges':'bytes'}})}
async function asset(e,p,h){const key=new URL(p+'?h='+h,self.registration.scope).href,c=await caches.open(ASSETS);
 const r=await c.match(key);if(r)return ranged(e.request,r);
 const net=await fetch(key,{cache:'no-cache'});if(!net.ok)return net;
 const put=c.put(key,net.clone()).catch(()=>{});
 if(e.request.headers.get('range')){await put;return ranged(e.request,net)}
 e.waitUntil(put);return net}
self.addEventListener('fetch',e=>{const q=e.request;if(q.method!=='GET')return;const u=new URL(q.url);if(u.origin!==location.origin)return;
 const p=relPath(u);if(p===null)return;
 if(!pruned&&p!==''&&p!=='index.html'&&q.mode!=='navigate')e.waitUntil(prune());
 if(q.headers.get('x-ctm-load'))return;  /* jload.js fills the cache itself */
 if(q.mode==='navigate'||p===''||p==='index.html'){e.respondWith((async()=>{const c=await caches.open(SHELL);
   /* network first (fresh build), but after 4 s on a slow line the saved copy answers; with no saved copy keep waiting */
   const net=fetch(q,{cache:'no-cache'}).then(r=>{if(r.ok&&!u.search)e.waitUntil(c.put('index.html',r.clone()));return r});
   const old=c.match('index.html');
   const slow=new Promise(ok=>setTimeout(ok,4000)).then(()=>old).then(r=>r||net);
   try{return await Promise.race([net,slow])}catch(err){return (await old)||Response.error()}})());return}
 if(/\.json$/.test(p)||p==='manifest.webmanifest'){e.respondWith(fetch(q,{cache:'no-cache'}).then(r=>{if(r.ok&&!/^assets\.json$/.test(p)){const cp=r.clone();e.waitUntil(caches.open(SHELL).then(c=>c.put(p,cp)))}return r}).catch(()=>caches.match(new URL(p,self.registration.scope).href,{ignoreSearch:true})));return}
 e.respondWith((async()=>{const m=await man(),h=m.get(p);
  if(h){try{return await asset(e,p,h)}catch(err){const c=await caches.open(ASSETS);const any=await c.match(new URL(p,self.registration.scope).href,{ignoreSearch:true});return any?ranged(q,any):Response.error()}}
  const hit=await caches.match(q,{ignoreSearch:true});if(hit)return ranged(q,hit);
  return fetch(q)})())});
